const MONGODB_URI = process.env.MONGODB_URI || 'mongodb+srv://mahmoud:mahmoud@cluster0.t0jahho.mongodb.net/lexpro?retryWrites=true&w=majority&appName=Cluster0';

let bucket: mongoose.mongo.GridFSBucket;

export async function connectDatabase(): Promise<void> {
  try {
    const conn = await mongoose.connect(MONGODB_URI, {
      maxPoolSize: 10,
      minPoolSize: 2,
      serverSelectionTimeoutMS: 10000,
      socketTimeoutMS: 30000,
      connectTimeoutMS: 10000,
    });
    console.log('✅ MongoDB متصل:', MONGODB_URI);

    const db = conn.connection.db;
