export function Layout() {
  const [collapsed, setCollapsed] = useState(false);
  const navigate = useNavigate();
  const location = useLocation();
  const { token } = theme.useToken();

  const selectedKey = location.pathname;
  const openKeys: string[] = [];
  if (selectedKey.startsWith('/fees') || selectedKey.startsWith('/expenses')) openKeys.push('accounts');
  if (selectedKey.startsWith('/settings/case-types') ||
      selectedKey.startsWith('/settings/announcement-types') ||
      selectedKey.startsWith('/settings/courts')) openKeys.push('elements');

  // Find the current page label
  const findLabel = (key: string): string => {
    for (const item of menuItems) {
      if (item.key === key) return item.label as string;
      const children = (item as any).children;
      if (children) {
        for (const child of children) {
          if (child.key === key) return child.label as string;
        }
      }
    }
    return 'LEX PRO';
  };

  return (
    <AntLayout style={{ minHeight: '100vh' }}>
      <Sider
        trigger={null}
        collapsible
        collapsed={collapsed}
        theme="dark"
        width={220}
        collapsedWidth={60}
        style={{
          background: 'linear-gradient(180deg, #1a2332 0%, #1e2a3a 100%)',
          boxShadow: '2px 0 8px rgba(0,0,0,0.15)',
          position: 'sticky',
          top: 0,
          height: '100vh',
          overflow: 'auto',
        }}
      >
        {/* --- Logo Area --- */}
        <div style={{
          height: 54,
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          borderBottom: '1px solid rgba(255,255,255,0.08)',
          padding: collapsed ? '4px' : '4px 14px',
          background: 'rgba(0,0,0,0.15)',
        }}>
          <img
            src={collapsed ? logoIcon : logoFull}
            alt="LEX PRO"
            style={{
              height: collapsed ? 30 : 34,
              objectFit: 'contain',
              transition: 'all 0.2s ease',
            }}
          />
        </div>

        {/* --- Menu --- */}
        <Menu
          mode="inline"
          selectedKeys={[selectedKey]}
          defaultOpenKeys={openKeys}
          items={menuItems}
          onClick={({ key }) => navigate(key)}
          theme="dark"
          style={{
            background: 'transparent',
            borderInlineEnd: 'none',
            padding: '6px 0',
            fontSize: 13,
          }}
        />
      </Sider>

      <AntLayout>
        <Header style={{
          background: token.colorBgContainer,
          padding: '0 16px',
          display: 'flex',
          alignItems: 'center',
          gap: 12,
          borderBottom: `1px solid ${token.colorBorderSecondary}`,
          height: 52,
          position: 'sticky',
          top: 0,
          zIndex: 10,
          boxShadow: '0 2px 8px rgba(0,0,0,0.06)',
        }}>
          <span
            onClick={() => setCollapsed(!collapsed)}
            style={{
              fontSize: 17,
              cursor: 'pointer',
              display: 'flex',
              alignItems: 'center',
              padding: '4px',
              borderRadius: 6,
              transition: 'background 0.2s',
            }}
            onMouseEnter={(e) => e.currentTarget.style.background = token.colorFillSecondary}
            onMouseLeave={(e) => e.currentTarget.style.background = 'transparent'}
          >
            {collapsed ? <MenuUnfoldOutlined /> : <MenuFoldOutlined />}
          </span>
          <span style={{
            fontSize: 15,
            fontWeight: 600,
            color: '#2c3e50',
          }}>
            {findLabel(selectedKey)}
          </span>
        </Header>
        <Content style={{
          margin: 0,
          padding: 14,
          overflow: 'auto',
          background: '#f0f2f5',
        }}>
          <Outlet />
        </Content>
      </AntLayout>
    </AntLayout>
  );
}

import { Button, Space, Input } from 'antd';
import { PlusOutlined, EditOutlined, DeleteOutlined, SearchOutlined } from '@ant-design/icons';
import { Typography } from 'antd';

const { Title, Text } = Typography;

interface PageHeaderProps {
  title: string;
  subtitle?: string;
  onAdd?: () => void;
  onEdit?: () => void;
  onDelete?: () => void;
  searchValue?: string;
  onSearch?: (value: string) => void;
  searchPlaceholder?: string;
  addLabel?: string;
  editLabel?: string;
  deleteLabel?: string;
}

export function PageHeader({
  title,
  subtitle,
  onAdd,
  onEdit,
  onDelete,
  searchValue,
  onSearch,
  searchPlaceholder = 'بحث...',
  addLabel = 'إضافة +',
  editLabel = 'تعديل',
  deleteLabel = 'حذف',
}: PageHeaderProps) {
  return (
    <div style={{ marginBottom: 12 }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 10 }}>
        <div>
          <Title level={4} style={{ margin: 0, color: '#2c3e50' }}>{title}</Title>
          {subtitle && <Text type="secondary" style={{ fontSize: 13 }}>{subtitle}</Text>}
        </div>
        <Space size="middle">
          {onAdd && (
            <Button
              type="primary"
              icon={<PlusOutlined />}
              onClick={onAdd}
              style={{ background: '#27ae60', borderColor: '#27ae60', height: 38, paddingInline: 18, fontSize: 14 }}
            >
              {addLabel}
            </Button>
          )}
          {onEdit && (
            <Button
              icon={<EditOutlined />}
              onClick={onEdit}
              style={{ background: '#2980b9', borderColor: '#2980b9', color: '#fff', height: 38, paddingInline: 18, fontSize: 14 }}
            >
              {editLabel}
            </Button>
          )}
          {onDelete && (
            <Button
              danger
              icon={<DeleteOutlined />}
              onClick={onDelete}
              style={{ background: '#c0392b', borderColor: '#c0392b', height: 38, paddingInline: 18, fontSize: 14 }}
            >
              {deleteLabel}
            </Button>
          )}
        </Space>
      </div>
      {onSearch && (
        <Input
          placeholder={searchPlaceholder}
          value={searchValue}
          onChange={(e) => onSearch(e.target.value)}
          prefix={<SearchOutlined style={{ color: '#bfbfbf' }} />}
          style={{ maxWidth: 380 }}
        />
      )}
    </div>
  );
}

